// 旧泵站的三条路线在地下室汇合。学院里拿到的线索可以解锁额外行动。
function pumpChoice(text, next, blood, spirit, favor, result, flags = [], requiredFlag = '') {
  return {text, next, blood, spirit, favor, result, flags, requiredFlag, requiredSpirit: 0};
}

function pumpChapter(title, paragraphs, choices) {
  return {title, text: paragraphs.join('\n\n'), ending: false, choices};
}

